-- ============================================
-- GoDesi Analytics: load Open Food Facts (Phase 2, Part B)
-- Role: LOADER. Bronze rule: load as-is, every column VARCHAR.
-- ============================================
USE SECONDARY ROLES NONE;
USE ROLE LOADER;
USE WAREHOUSE GODESI_WH;

-- 2.2 FILE FORMAT: how to read the TSV
CREATE FILE FORMAT IF NOT EXISTS GODESI_RAW.OPEN_FOOD_FACTS.OFF_TSV
    TYPE                         = CSV
    FIELD_DELIMITER              = '\t'
    SKIP_HEADER                  = 1
    ENCODING                     = 'UTF8'
    FIELD_OPTIONALLY_ENCLOSED_BY = '"'      -- 56 fields are wrapped in "..."
    ESCAPE_UNENCLOSED_FIELD      = NONE     -- 3 rows contain a backslash; treat it as normal text
    NULL_IF                      = ('')
    EMPTY_FIELD_AS_NULL          = TRUE
    COMMENT                      = 'Open Food Facts India export (tab-separated)';

-- 2.3 STAGE: landing folder for all raw files (sub-folders: off/, batch1/, batch2/)
CREATE STAGE IF NOT EXISTS GODESI_RAW.ERP.RAW_STAGE
    COMMENT = 'Landing area for raw files before COPY INTO';
-- 2.4 UPLOAD: done in Snowsight (+ Files, path = off). Check it arrived:
LIST @GODESI_RAW.ERP.RAW_STAGE/off/;
-- If a file lands in the stage root by mistake (empty path box), move it once:
-- COPY FILES INTO @GODESI_RAW.ERP.RAW_STAGE/off/ FROM @GODESI_RAW.ERP.RAW_STAGE/ FILES = ('off_india_raw.tsv');
-- REMOVE @GODESI_RAW.ERP.RAW_STAGE/off_india_raw.tsv;

