SELECT COUNT(*) FROM GODESI_RAW.OPEN_FOOD_FACTS.PRODUCTS;          -- 26293

SELECT *
FROM TABLE(GODESI_RAW.INFORMATION_SCHEMA.COPY_HISTORY(
    TABLE_NAME => 'GODESI_RAW.OPEN_FOOD_FACTS.PRODUCTS',
    START_TIME => DATEADD(hour, -24, CURRENT_TIMESTAMP())));       -- ERROR_COUNT = 0

